package com.example.it140p_spark

import androidx.compose.runtime.Composable
import androidx.compose.material3.ExperimentalMaterial3Api
import androidx.compose.material3.TopAppBarDefaults
import com.example.it140p_spark.ui.components.AppBar
import com.example.it140p_spark.ui.components.NavBar
import com.example.it140p_spark.ui.components.navItems
import com.example.it140p_spark.ui.layout.ScaffoldLayout
import com.example.it140p_spark.ui.screens.BillingScreen
import com.example.it140p_spark.ui.screens.EnrollmentScreen
import com.example.it140p_spark.ui.screens.RecordsScreen
import com.example.it140p_spark.ui.screens.ScheduleScreen
import androidx.compose.runtime.getValue
import androidx.compose.runtime.mutableIntStateOf
import androidx.compose.runtime.remember
import androidx.compose.runtime.setValue
import androidx.compose.ui.Modifier
import androidx.compose.ui.input.nestedscroll.nestedScroll

/* todo: save current screen state when phone is rotated to landscape/portrait */
@OptIn(ExperimentalMaterial3Api::class)
@Composable
fun App(studentId: String) {
    var selectedIndex by remember { mutableIntStateOf(0) }
    val selectedNavItem = navItems[selectedIndex]
    val scrollBehavior = TopAppBarDefaults.enterAlwaysScrollBehavior()

    ScaffoldLayout(
        modifier = Modifier.nestedScroll(scrollBehavior.nestedScrollConnection),
        topBar = {
            AppBar(
                route = selectedNavItem.route,
                scrollBehavior = scrollBehavior
            )
        },
        bottomBar = {
            NavBar(
                selectedIndex = selectedIndex,
                onItemSelected = { selectedIndex = it }
            )
        },
    ) { padding ->
        when (selectedNavItem.route) {
            "schedule" -> ScheduleScreen(padding)
            "enroll" -> EnrollmentScreen(studentId, padding)
            "billing" -> BillingScreen(padding)
            "records" -> RecordsScreen(padding)
        }
    }
}

package com.example.it140p_spark.data

import kotlinx.serialization.Serializable
import kotlinx.serialization.SerialName

@Serializable
data class Course(
    @SerialName("CourseID") val courseId: String,
    @SerialName("CourseName") val courseName: String,
    @SerialName("CourseCode") val courseCode: String,
    @SerialName("CourseUnits") val courseUnits: String
)

@Serializable
data class CourseSearchResponse(
    val status: String,
    val message: String? = null,
    val data: List<Course>? = null
)

@Serializable
data class CourseEnlistedSearchResponse(
    val status: String,
    val message: String? = null,
    val data: List<Course>? = null
)

@Serializable
data class EnrollmentResponse(
    val status: String,
    val message: String
)

package com.example.it140p_spark.data
import kotlinx.serialization.Serializable
@Serializable data class FinalizationEnlistedCourse( val CourseEnlistedID: Int, val CourseID: Int, val CourseName: String, val CourseCode: String, val CourseUnits: Int, val EnlistmentID: Int, val SectionID: Int?, val SectionCODE: String?, val Room: String?, val Capacity: Int?, val CurrentEnrolled: Int?, val InstructorFirstName: String?, val InstructorLastName: String? )
@Serializable data class StudentFinalizationDataResponse( val status: String, val courses: List<FinalizationEnlistedCourse>? = null, val term: String? = null, val message: String? = null )
@Serializable data class FinalizeEnrollmentResponse( val status: String, val message: String? = null, val enrollment_id: Int? = null )

package com.example.it140p_spark.data

import kotlinx.serialization.Serializable
import kotlinx.serialization.SerialName

@Serializable
data class EnlistedCourse(
    @SerialName("CourseID") val courseId: String,
    @SerialName("CourseName") val courseName: String,
    @SerialName("CourseCode") val courseCode: String,
    @SerialName("SectionID") val sectionId: String?,
    @SerialName("SectionCode") val sectionCode: String?,
    @SerialName("CourseUnits") val courseUnits: String,
    @SerialName("Day") val day: String?,
    @SerialName("StartTime") val startTime: String?,
    @SerialName("EndTime") val endTime: String?
)

data class GroupedSection(
    val courseId: String,
    val courseName: String,
    val courseCode: String,
    val sectionId: String,
    val sectionCode: String,
    val courseUnits: String,
    val schedules: List<ScheduleEntry>
)

data class ScheduleEntry(
    val day: String,
    val startTime: String,
    val endTime: String
)

@Serializable
data class CourseSectionSearchResponse(
    val status: String,
    val message: String? = null,
    val data: List<EnlistedCourse>? = null
)

